CM_TalentDesc_ptBR.sorted_sub_keys = {}
for k in pairs(CM_TalentDesc_ptBR.substitutions) do
    table.insert(CM_TalentDesc_ptBR.sorted_sub_keys, k)
end
table.sort(CM_TalentDesc_ptBR.sorted_sub_keys, function(a, b)
    return string.len(a) > string.len(b)
end)

